"""Summarize executed synthesis and cycle counts; never invent power/timing."""
from pathlib import Path
import argparse,json,re
import numpy as np
r=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--assumed-clock-mhz',type=float,default=100.);p.add_argument('--assumed-power-w',type=float);a=p.parse_args()
if a.assumed_clock_mhz<=0 or not np.isfinite(a.assumed_clock_mhz):raise ValueError('Clock must be positive and finite')
if a.assumed_power_w is not None and (a.assumed_power_w<=0 or not np.isfinite(a.assumed_power_w)):raise ValueError('Power must be positive and finite')
metrics=json.loads((r/'reports/ds2_metrics.json').read_text());core=json.loads((r/'reports/synthesis/trained_core/result.json').read_text());board=json.loads((r/'reports/synthesis/trained_board/result.json').read_text());text=(r/'reports/trained_qnn_checked.log').read_text();cycles=list(map(int,re.findall(r'cycles=(\d+)',text)));assert len(cycles)==10 and 'PASS 10/10' in text
latency=float(np.mean(cycles)/(a.assumed_clock_mhz*1000));energy=None if a.assumed_power_w is None else a.assumed_power_w*latency
q=metrics['quantized_current_irn'];report={'synthesis':{'core':core,'board_wrapper':board},'cycle_simulation':{'status':'PASS','vectors':len(cycles),'engine_cycles':cycles,'mean_engine_cycles':float(np.mean(cycles)),'scope':'RTL simulation start-to-done; excludes CWT, acquisition, map loading and debounce'},'clock_to_time':{'status':'ESTIMATED','assumed_achieved_clock_MHz':a.assumed_clock_mhz,'engine_latency_ms':latency,'cycles_in_0_35ms':a.assumed_clock_mhz*350,'latency_target_status':'PASS' if latency<.35 else 'FAIL','timing_closure':'BLOCKED: Vivado/implementation tools unavailable'},'energy':{'status':'NOT TESTED' if energy is None else 'ESTIMATED','assumed_power_W':a.assumed_power_w,'energy_mJ_per_inference':energy,'target_status':'NOT TESTED' if energy is None else 'PASS' if energy<.07 else 'FAIL','formula':'E_mJ = P_W * latency_ms; no measured power provided'},'accuracy':{'status':'PASS','meaning':'held-out evaluation executed','DS2_beats':q['samples'],'overall_accuracy':q['accuracy'],'macro_f1':q['macro_f1'],'target_strictly_greater_than':.996,'target_status':'PASS' if q['accuracy']>.996 else 'FAIL'},'paper_table_I_reference':{'scope':'reported by supplied paper, not measured here; different architecture/protocol and CWT in FPGA','LUT':11364,'FF':21118,'DSP':0,'BRAM_reported':28,'model_kbit':25.4,'latency_ms':.350,'FPGA_core_power_W':.219,'whole_board_power_W':1.02,'FPGA_core_energy_mJ':.0767,'whole_board_energy_mJ':.357,'accuracy':.995},'NOT_TESTED':['post-synthesis functional simulation/formal equivalence','place/route','achieved Fmax','physical power/energy','bitstream generation','board programming','physical ADC connection'],'resource_notes':'LUT primitives are synthesis counts; no placed slice packing or device timing proof. BRAM units are explicit RAMB36E1/RAMB18E1 primitives.'}
(r/'reports/performance_summary.json').write_text(json.dumps(report,indent=2))
lines=['# Executed performance and feasibility','', f'**Accuracy target: {report["accuracy"]["target_status"]}. Latency target: {report["clock_to_time"]["latency_target_status"]} under the declared {a.assumed_clock_mhz:g} MHz assumption. Energy result: {report["energy"]["status"]}.**','', '| Scope | LUT primitives | FF | RAMB36E1 | RAMB18E1 | DSP48E1 | Status |','|---|---:|---:|---:|---:|---:|---|']
for name,v in [('QNN core',core),('Stored-map Basys 3 wrapper',board)]:lines.append(f'| {name} | {v["LUT_primitives"]} | {v["FF"]} | {v["RAMB36"]} | {v["RAMB18"]} | {v["DSP48"]} | {v["status"]} — generic synthesis |')
lines += ['', 'Counts come from YoWASP Yosys 0.48 `synth_xilinx -family xc7`, with frozen trained ROMs. The wrapper totals include its QNN submodule. Both flows completed `check` with zero reported problems. Reports, mapped EDIF/JSON and exact ROM/source hashes are in `reports/synthesis/`. This is generic 7-series synthesis, not Vivado utilization, placement, routing, timing closure or physical verification.','',f'The ten-vector RTL check measured {int(np.mean(cycles)):,} engine clock cycles per vector. At an **assumed achieved {a.assumed_clock_mhz:g} MHz**, the derived latency is **{latency:.5f} ms (ESTIMATED)**, versus the requested <0.35 ms. The same budget allows only {a.assumed_clock_mhz*350:,.0f} cycles. Clock frequency has not been demonstrated after routing. Host CWT, map loading, signal acquisition and button debounce are excluded. The beat itself requires 219 post-R samples (0.6083 seconds at 360 Hz), a separate algorithmic look-ahead.','', 'Power and energy have not been measured. No LUT-based energy guess is substituted. If an explicit power assumption is supplied, `--assumed-power-w` produces an ESTIMATED value using `E_mJ = P_W × latency_ms`. Such a value is not a measured acceptance result.','', 'The supplied paper Table I reports 11,364 LUTs, 21,118 FFs, 0 DSPs, 28 BRAMs, 0.350 ms, FPGA-core 0.219 W/0.0767 mJ, and whole-board 1.02 W/0.357 mJ for its balanced design. These are paper-reported values. Its CWT is in FPGA; ours is on the host. Its 25.4 Kbit model and six-layer architecture differ from this preserved 9,293-parameter model. Its exact DS1/DS2 protocol is not disclosed in the supplied paper. These differences prevent a like-for-like superiority claim.','', 'The original narrow program ROM was accessed at eighteen independent addresses per instruction. The repaired engine reads one 288-bit instruction assembled offline from the same eighteen 16-bit fields. The original word files and arithmetic remain compatible; the `.mem.wide` companion is required. Original eight-vector parity and new trained ten-vector parity pass. No formal or post-synthesis netlist equivalence run was performed.','', 'Earlier tool failures and report-parser failures are retained under `reports/baseline/`, `reports/synthesis/report_path_failure/` and `reports/synthesis/board_report_parser_failure.json`. A console stream stopped printing at ABC, so final internal `-l` logs, structured statistics and output netlists are used as completion evidence.','', 'Vivado and a physical Basys 3 were unavailable. Timing/implementation is BLOCKED; programming, physical ADC acquisition, board power and energy remain NOT TESTED. A user-run Vivado Tcl flow is provided and labeled unexecuted.']
(r/'reports/PERFORMANCE.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'core':core['status'],'board':board['status'],'latency_ms_estimated':latency,'accuracy':q['accuracy'],'energy_status':report['energy']['status']},indent=2))
